import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useTravelContextValue } from '../../context'
import { TRAVEL_ACTIONS } from '../actions'

export const useProfileServiceCall = (actionsCall = () => {}) => {
  const [myProfileState, dispatch] = useTravelContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(
    (payload = {}) => {
      callApi(
        actionsCall({
          ...payload,
        })
      )
    },
    [callApi, actionsCall]
  )
  return [myProfileState, request]
}

// Following upload pattern for file uploads
export const useUploadTravelPassenger = () => {
  const [travelState, dispatch] = useTravelContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) =>
    await callApi(TRAVEL_ACTIONS.uploadTravelPassenger(payload))

  return [travelState, request]
}

