import { TravelDetailStyle, DatePickerStyle, Footer } from './index.style'
import {
  Container,
  CustomText,
  Button,
  InnerInput,
  Select,
} from '../../../../../../components'
import { useState, useEffect, useCallback } from 'react'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import { LANG_STRINGS } from '../../../../../../lang/index'
import { TRAVEL_STEPS } from '../../../constant'
import { Row } from '../../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { Datepicker } from '@mobiscroll/react'
import StatusInfoCard from '../../../../../../components/StatusInfoCard'
import AutoSearchModal from '../../../../../../components/AutoSearchModal'
import moment from 'moment'
import { useParams } from 'react-router'
import {
  useGetTravelRegions,
  useCreateTravelDraft,
  useUpdateTravelDraft,
  useGetTravelDetails,
} from '../../../state/hooks/useTravelState'
import TitleError from '../../../../../../components/TitleError'
import {
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { useHistory } from 'react-router-dom'
import { regex } from '../../../../../../constants/regex'

function TravelDetailContainer() {
  const { id } = useParams()
  const history = useHistory()
  const [{ getTravelRegionData = {} }, getTravelRegionsRequest] =
    useGetTravelRegions()
  const [{ createTravelDraftData = {} }, createTravelDraftRequest] =
    useCreateTravelDraft()
  const [, updateTravelDraftRequest] = useUpdateTravelDraft()
  const [{ getTravelDetailsData = {} }, getTravelDetailsRequest] =
    useGetTravelDetails()
  const [{ createTravelDraftStatus, updateTravelDraftStatus }] =
    useErrorContextValue()
  const { resetError } = useResetError()

  const [selectedTrip, setSelectedTrip] = useState('domestic')
  const [selectedProtection, setSelectedProtection] = useState('individual')
  const [schengenVisa, setSchengenVisa] = useState(false)
  const [additionalCountInput, setAdditionalCountInput] = useState('')
  const [errorHandling, setErrorHandling] = useState({
    start_date: false,
    end_date: false,
    name: false,
    city_origin: false,
    city_destination: false,
    country_destination: false,
  })
  const [formValues, setFormValues] = useState({
    purchase_type: 'new-purchase',
    product_code: 'travel-protection',
    start_date: '',
    end_date: '',
    destination: [],
    destination_data: [],
    source: '',
    travel_type: 'domestic',
    policy_type: 'individual',
    schengen_visa: false,
    additional_member_count: {
      total: 0,
      adult: 0,
      kids: 0,
      parents: 0,
      siblings: 0,
    },
    customer_data: {
      name: '',
      main_traveller: {
        name: '',
      },
    },
  })

  const schengenCountries = [
    'AUSTRIA',
    'BELGIUM',
    'BULGARIA',
    'CZECH REPUBLIC',
    'CROATIA',
    'DENMARK',
    'ESTONIA',
    'FINLAND',
    'FRANCE',
    'GERMANY',
    'GREECE',
    'HUNGARY',
    'ICELAND',
    'ITALY',
    'LATVIA',
    'LITHUANIA',
    'LIECHTENSTEIN',
    'LUXEMBOURG',
    'MALTA',
    'NORWAY',
    'NETHERLANDS',
    'POLAND',
    'PORTUGAL',
    'ROMANIA',
    'SLOVAKIA',
    'SLOVENIA',
    'SPAIN',
    'SWEDEN',
    'SWITZERLAND',
  ]

  useEffect(() => {
    getTravelRegionsRequest()
  }, [getTravelRegionsRequest])

  useEffect(() => {
    if (id) {
      getTravelDetailsRequest({ draftQuoteId: id })
    }
  }, [getTravelDetailsRequest, id])

  useEffect(() => {
    if (Object.keys(getTravelDetailsData).length > 0) {
      setSelectedTrip(
        getTravelDetailsData?.policy_details?.travel_type || 'domestic'
      )
      setSelectedProtection(
        getTravelDetailsData?.policy_details?.policy_type || 'individual'
      )
      setSchengenVisa(
        getTravelDetailsData?.policy_details?.schengen_visa || false
      )
      setFormValues({
        product_code: 'travel-protection',
        start_date: getTravelDetailsData?.policy_details?.start_date || '',
        end_date: getTravelDetailsData?.policy_details?.end_date || '',
        package_type: 'travel-protection-executive',
        destination: getTravelDetailsData?.policy_details?.destination || [],
        destination_data:
          getTravelDetailsData?.policy_details?.destination_data || [],
        source: getTravelDetailsData?.policy_details?.source || '',
        travel_type:
          getTravelDetailsData?.policy_details?.travel_type || 'domestic',
        policy_type:
          getTravelDetailsData?.policy_details?.policy_type || 'individual',
        schengen_visa:
          getTravelDetailsData?.policy_details?.schengen_visa || false,
        additional_member_count: {
          total:
            getTravelDetailsData?.policy_details?.additional_member_count
              ?.total || 0,
          adult:
            getTravelDetailsData?.policy_details?.additional_member_count
              ?.adult || 0,
          kids:
            getTravelDetailsData?.policy_details?.additional_member_count
              ?.kids || 0,
          parents:
            getTravelDetailsData?.policy_details?.additional_member_count
              ?.parents || 0,
          siblings:
            getTravelDetailsData?.policy_details?.additional_member_count
              ?.siblings || 0,
        },
        customer_data: {
          name: getTravelDetailsData?.policy_details?.customer_data
            ?.main_traveller?.name,
          main_traveller: {
            name:
              getTravelDetailsData?.policy_details?.customer_data
                ?.main_traveller?.name || '',
          },
        },
      })
    }
  }, [getTravelDetailsData])

  useEffect(() => {
    setAdditionalCountInput(formValues.additional_member_count.total.toString())
  }, [formValues.additional_member_count.total])

  useEffect(() => {
    if (updateTravelDraftStatus === 'success') {
      if (id) {
        history.push(`/travel/insured_package/${id}`)
      }
      resetError(['updateTravelDraftStatus'])
    }
    if (createTravelDraftStatus === 'success') {
      if (createTravelDraftData?.draft_id) {
        history.push(
          `/travel/insured_package/${createTravelDraftData?.draft_id}`
        )
      }
      resetError(['createTravelDraftStatus'])
    }
  }, [
    updateTravelDraftStatus,
    createTravelDraftStatus,
    resetError,
    createTravelDraftData,
    history,
    id,
  ])

  const handleTripToggle = (type) => {
    setSelectedTrip(type)
    setFormValues((formValue) => ({
      ...formValue,
      source: type === 'international' ? 'Indonesia' : '',
      destination: '',
      destination_data: [],
      travel_type: type,
    }))
    if (type === 'international') {
      setErrorHandling((error) => ({
        ...error,
        city_destination: false,
        city_origin: false,
      }))
    } else {
      setErrorHandling((error) => ({ ...error, country_destination: false }))
      setSchengenVisa(false)
      setFormValues((formValue) => ({ ...formValue, schengen_visa: false }))
    }
  }

  const handlePolicyTypeToggle = (type) => {
    setSelectedProtection(type)
    // setFormValues(formValue => ({
    //   ...formValue,
    //   additional_member_count: {
    //     ...formValue.additional_member_count,
    //     adult: type === 'family' ? 1 : 0,
    //     kids: type === 'family' ? 1 : 0
    //   },
    //   policy_type: type
    // }))
    // setFormValues(formValue => ({ ...formValue, additional_passengers: type === 'group' ? 2 : type === 'family' ? 1 : 0 }))
    setFormValues((formValue) => ({
      ...formValue,
      additional_member_count: {
        ...formValue.additional_member_count,
        total: type === 'individual' ? 0 : type === 'group' ? 2 : 1,
      },
      policy_type: type,
    }))
  }

  const handleNameChange = (value) => {
    setFormValues((formValue) => ({
      ...formValue,
      customer_data: {
        ...formValue.customer_data,
        name: value,
        main_traveller: {
          ...formValue.customer_data.main_traveller,
          name: value,
        },
      },
    }))
    setErrorHandling((error) => ({ ...error, name: false }))
  }

  // const convertCityObject = (list) => {
  //   if (!list || list.length === 0) {
  //     return null
  //   }

  const handleBackButton = useCallback(() => {
    history.push('/dashboard')
  }, [history])

  const convertCountryObject = (list) => {
    if (!list || list.length === 0) {
      return null
    }
    const Object = {}
    list.forEach((countryName) => {
      Object[countryName] = { country_name: countryName }
    })
    return Object
  }

  const findLocationsByNames = (names, data) => {
    const result = []
    if (!Array.isArray(names)) {
      names = [names]
    }
    for (const name of names) {
      let foundLocation = null
      if (data && data.cities && Array.isArray(data.cities)) {
        foundLocation = data.cities.find(
          (city) => city.city_name?.toLowerCase() === name?.toLowerCase()
        )
      }
      if (
        !foundLocation &&
        data &&
        data.origin_countries &&
        Array.isArray(data.origin_countries)
      ) {
        foundLocation = data.origin_countries.find(
          (country) =>
            country.country_name?.toLowerCase() === name?.toLowerCase()
        )
      }
      if (
        !foundLocation &&
        data &&
        data.destination_countries &&
        Array.isArray(data.destination_countries)
      ) {
        foundLocation = data.destination_countries.find(
          (country) =>
            country.country_name?.toLowerCase() === name?.toLowerCase()
        )
      }
      if (foundLocation) {
        result.push(foundLocation)
      }
    }
    return result
  }

  const validateFields = useCallback((data) => {
    let isError = false
    if (!data.start_date) {
      setErrorHandling((error) => ({ ...error, start_date: true }))
      isError = true
    }
    if (!data.end_date) {
      setErrorHandling((error) => ({ ...error, end_date: true }))
      isError = true
    }
    if (!data.customer_data.main_traveller.name) {
      setErrorHandling((error) => ({ ...error, name: true }))
      isError = true
    }
    if (!data.source) {
      setErrorHandling((error) => ({ ...error, city_origin: true }))
      isError = true
    }
    if (data.destination.length === 0 || data.destination[0] === undefined) {
      setErrorHandling((error) => ({
        ...error,
        city_destination: true,
        country_destination: true,
      }))
      isError = true
    }
    if (
      data.customer_data.name &&
      !regex.nameRegexAlphanumericButContainAtleastTwoCharacters.test(
        data.customer_data.name
      )
    ) {
      setErrorHandling((error) => ({
        ...error,
        name: LANG_STRINGS.nameShouldContain2CharacterAtleast,
      }))
      isError = true
    }
    return isError
  }, [])

  const handleSubmit = useCallback(
    (data) => {
      const hasError = validateFields(data)
      if (hasError) {
        return
      }
      data = {
        ...data,
        protection: 'individual',
      }

      if (id) {
        updateTravelDraftRequest({
          body: {
            section: 'protection_type',
            sub_section: 'product_criteria',
            data: data,
          },
          draftQuoteId: id,
        })
      } else {
        createTravelDraftRequest({
          section: 'protection_type',
          sub_section: 'product_criteria',
          data: data,
        })
      }
    },
    [createTravelDraftRequest, updateTravelDraftRequest, id, validateFields]
  )

  const fieldData = {
    mainTraveller: {
      label: 'Traveler Utama',
      type: 'input',
      name: 'name',
      placeholder: 'Nama sesuai KTP',
      handleChange: handleNameChange,
      defaultValues: formValues?.customer_data?.main_traveller?.name || '',
      render: true,
    },
    tripType: {
      label: 'Tipe Perjalanan',
      type: 'switch-trip',
      name: 'trip',
      render: true,
    },
    destination: {
      label: 'Destinasi Perjalanan',
      type: 'destination',
      name: 'location',
      defaultOrigin: formValues?.source || undefined,
      defaultDestination: formValues?.destination || undefined,
      render: true,
    },
    schengen: {
      label:
        'Apakah Anda ingin melakukan pengajuan pembuatan Visa Schengen juga?',
      type: 'schengen',
      name: 'schengen',
      render: schengenCountries.some((country) =>
        formValues?.destination.includes(country)
      ),
    },
    protectionPeriod: {
      label: 'Periode Perlindungan',
      type: 'start-date',
      name: 'start-date',
      defaultValues: formValues?.start_date || undefined,
      render: true,
    },
    protectionPeriod2: {
      label: '',
      type: 'end-date',
      name: 'end-date',
      defaultValues: formValues?.end_date || undefined,
      render: true,
    },
    protectionType: {
      label: 'Jenis Perlindungan',
      type: 'switch-protection',
      name: 'protection',
      render: true,
    },
    additionalPassengers: {
      label: 'Tertanggung Tambahan (tidak termasuk saya)',
      type: 'additional-passengers',
      name: 'additional',
      render: selectedProtection !== 'individual',
    },
    // child: {
    //   label: 'Anak (3 bln - 18 thn)',
    //   type: 'dropdown',
    //   name: 'child',
    //   dropdownOptions: CHILD_OPTIONS,
    //   defaultValues: formValues?.additional_member_count?.kids || undefined,
    //   render: selectedProtection === 'family'
    // }
  }

  const renderFormField = (
    title,
    type,
    name,
    dropdownOptions,
    placeholder,
    onChange,
    defaultValues,
    origin,
    destination
  ) => {
    let componentField
    switch (type) {
      case 'input':
        componentField = (
          <div className="mg-15">
            {errorHandling.name && (
              <TitleError
                title=""
                error={
                  typeof errorHandling.name === 'string'
                    ? errorHandling.name
                    : LANG_STRINGS.required
                }
              />
            )}
            <InnerInput
              placeholder={placeholder}
              onChange={(e) => onChange(e.target.value)}
              name={name}
              value={defaultValues}
              errorField={errorHandling.name ? name : ''}
            />
          </div>
        )
        break
      case 'start-date':
        componentField = (
          <div className="mg-15">
            <DatePickerStyle
              error={errorHandling.start_date ? LANG_STRINGS.required : ''}
            >
              {errorHandling.start_date && (
                <TitleError title="" error={LANG_STRINGS.required} />
              )}
              <Datepicker
                theme="ios"
                themeVariant="light"
                touchUi
                display="center"
                dateFormat="DD/MM/YYYY"
                inputComponent="input"
                calendarScroll="vertical"
                calendarType="month"
                className="calendar"
                value={
                  formValues.start_date ? new Date(formValues.start_date) : null
                }
                min={new Date()}
                max={moment().add(1, 'y').toDate()}
                inputProps={{
                  placeholder: LANG_STRINGS.startTrip,
                  className: 'calendar input-calendar-icon',
                }}
                onChange={(e) => {
                  const newDate = moment(e.value).format('YYYY-MM-DD')
                  if (formValues.start_date !== newDate) {
                    setFormValues((prev) => ({
                      ...prev,
                      start_date: newDate,
                      end_date:
                        prev.end_date &&
                        moment(prev.end_date).isBefore(moment(newDate))
                          ? '' // clear end_date if it's before start_date
                          : prev.end_date,
                    }))
                    setErrorHandling((error) => ({
                      ...error,
                      start_date: false,
                    }))
                  }
                }}
              />
            </DatePickerStyle>
          </div>
        )
        break
      case 'end-date':
        componentField = (
          <div className="mg-15">
            <DatePickerStyle
              error={errorHandling.end_date ? LANG_STRINGS.required : ''}
            >
              {errorHandling.end_date && (
                <TitleError title="" error={LANG_STRINGS.required} />
              )}
              <Datepicker
                theme="ios"
                themeVariant="light"
                touchUi
                // controls={['date']}
                dateFormat="DD/MM/YYYY"
                display="center"
                inputComponent="input"
                calendarScroll="vertical"
                calendarType="month"
                className="calendar"
                value={
                  formValues.end_date ? new Date(formValues.end_date) : null
                }
                // min={formValues?.start_date ? moment(formValues?.start_date).add(1, 'd').format('YYYY-MM-DD') : new Date()}
                min={
                  formValues?.start_date
                    ? moment(formValues?.start_date)
                        .add(1, 'd')
                        .format('YYYY-MM-DD')
                    : moment().add(1, 'd').format('YYYY-MM-DD')
                }
                // max={new Date(new Date().setFullYear(new Date().getFullYear() + 1)).setMonth(new Date().getMonth() + 6)}
                max={
                  formValues?.start_date
                    ? moment(formValues?.start_date)
                        .add(183, 'days')
                        .format('YYYY-MM-DD')
                    : moment().add(1, 'y').format('YYYY-MM-DD')
                }
                inputProps={{
                  placeholder: LANG_STRINGS.endTrip,
                  className: 'calendar input-calendar-icon',
                }}
                onChange={(e) => {
                  const newEnd = moment(e.value).format('YYYY-MM-DD')
                  if (formValues.end_date !== newEnd) {
                    setFormValues((prev) => ({
                      ...prev,
                      end_date: newEnd,
                    }))
                    setErrorHandling((error) => ({ ...error, end_date: false }))
                  }
                }}
              />
            </DatePickerStyle>
          </div>
        )
        break
      case 'destination':
        componentField = (
          <div className="mg-15">
            {selectedTrip === 'domestic' ? (
              <>
                {errorHandling.city_origin && (
                  <TitleError title="" error={LANG_STRINGS.required} />
                )}
                <AutoSearchModal
                  key="domestic-origin"
                  data={getTravelRegionData?.cities?.filter(
                    (city) => !formValues?.destination?.includes(city.city_name)
                  )}
                  onSelect={(value) => {
                    setFormValues((formValue) => ({
                      ...formValue,
                      source: value,
                    }))
                    setErrorHandling((error) => ({
                      ...error,
                      city_origin: false,
                    }))
                  }}
                  title="Dari"
                  displayKey="city_name"
                  dataKey="city_name"
                  name="city_origin"
                  errorField={errorHandling.city_origin ? 'city_origin' : ''}
                  placeholder="Dari"
                  defaultValue={origin}
                />
              </>
            ) : (
              <AutoSearchModal
                key="international-origin"
                data={getTravelRegionData?.origin_countries}
                title="Dari"
                displayKey="country_name"
                dataKey="country_name"
                name={name}
                disabled
                defaultValue="Indonesia"
              />
            )}
            {selectedTrip === 'domestic' ? (
              <>
                {errorHandling.city_destination && (
                  <TitleError title="" error={LANG_STRINGS.required} />
                )}
                <AutoSearchModal
                  key="domestic-destination"
                  data={getTravelRegionData?.cities?.filter(
                    (city) => !formValues?.source?.includes(city.city_name)
                  )}
                  title="Tujuan"
                  titleForMultiple="Tujuan"
                  displayKey="city_name"
                  dataKey="city_name"
                  name="city_destination"
                  maxSelectCount={1}
                  placeholder="Tujuan"
                  errorField={
                    errorHandling.city_destination ? 'city_destination' : ''
                  }
                  onSelect={(value) => {
                    setFormValues((formValue) => ({
                      ...formValue,
                      destination: [value],
                      destination_data: findLocationsByNames(
                        value,
                        getTravelRegionData
                      ),
                    }))
                    setErrorHandling((error) => ({
                      ...error,
                      city_destination: false,
                      country_destination: false,
                    }))
                  }}
                  defaultValue={destination?.[0]}
                />
              </>
            ) : (
              <>
                {errorHandling.country_destination && (
                  <TitleError title="" error={LANG_STRINGS.required} />
                )}
                <AutoSearchModal
                  key="international-destination"
                  data={getTravelRegionData?.destination_countries?.map(
                    (country) => ({ country_name: country.country_name })
                  )}
                  title="Tujuan"
                  titleForMultiple="Tujuan"
                  displayKey="country_name"
                  dataKey="country_name"
                  name="country_destination"
                  isMultiple
                  maxSelectCount={10}
                  placeholder="Tujuan"
                  errorField={
                    errorHandling.country_destination
                      ? 'country_destination'
                      : ''
                  }
                  onSelect={(value) => {
                    setFormValues((formValue) => ({
                      ...formValue,
                      destination: Object.keys(value),
                      destination_data: findLocationsByNames(
                        Object.keys(value),
                        getTravelRegionData
                      ),
                    }))
                    setErrorHandling((error) => ({
                      ...error,
                      city_destination: false,
                      country_destination: false,
                    }))
                    if (
                      !schengenCountries.some((country) =>
                        Object.values(value).some(
                          (item) => item.country_name === country
                        )
                      )
                    ) {
                      setSchengenVisa(false)
                      setFormValues((formValue) => ({
                        ...formValue,
                        schengen_visa: false,
                      }))
                    }
                  }}
                  defaultProviders={convertCountryObject(destination)}
                />
              </>
            )}
          </div>
        )
        break
      case 'switch-trip':
        componentField = (
          <Row align="center" justify="space-between" className="mg-15">
            <Button
              className={`select-buttons ${selectedTrip === 'domestic' ? 'selected' : ''}`}
              onClick={() => handleTripToggle('domestic')}
            >
              Domestik
            </Button>
            <Button
              className={`select-buttons ${selectedTrip === 'international' ? 'selected' : ''}`}
              onClick={() => handleTripToggle('international')}
            >
              International
            </Button>
          </Row>
        )
        break
      case 'schengen':
        componentField = (
          <Row align="center" justify="space-between" className="mg-15">
            <Button
              className={`select-buttons ${schengenVisa ? 'selected' : ''}`}
              onClick={() => {
                setSchengenVisa(true)
                setFormValues((formValue) => ({
                  ...formValue,
                  schengen_visa: true,
                }))
              }}
            >
              YA
            </Button>
            <Button
              className={`select-buttons ${!schengenVisa ? 'selected' : ''}`}
              onClick={() => {
                setSchengenVisa(false)
                setFormValues((formValue) => ({
                  ...formValue,
                  schengen_visa: false,
                }))
              }}
            >
              Tidak
            </Button>
          </Row>
        )
        break
      case 'switch-protection':
        componentField = (
          <Row align="center" justify="space-between" className="mg-15">
            <Button
              className={`select-buttons three-buttons ${selectedProtection === 'individual' ? 'selected' : ''}`}
              onClick={() => handlePolicyTypeToggle('individual')}
            >
              Individu
            </Button>
            <Button
              className={`select-buttons three-buttons ${selectedProtection === 'family' ? 'selected' : ''}`}
              onClick={() => handlePolicyTypeToggle('family')}
            >
              Keluarga
            </Button>
            <Button
              className={`select-buttons three-buttons ${selectedProtection === 'group' ? 'selected' : ''}`}
              onClick={() => handlePolicyTypeToggle('group')}
            >
              Grup
            </Button>
          </Row>
        )
        break
      case 'additional-passengers':
        componentField = (
          <div className="mg-15">
            <Row align="center" justify="space-between">
              <Button
                className={`select-buttons three-buttons ${formValues.additional_member_count.total <= (selectedProtection === 'group' ? 2 : 1) ? 'disabled-buttons' : ''}`}
                disabled={
                  formValues.additional_member_count.total <=
                  (selectedProtection === 'group' ? 2 : 1)
                }
                onClick={() =>
                  setFormValues((formValue) => ({
                    ...formValue,
                    additional_member_count: {
                      ...formValue.additional_member_count,
                      total: formValue.additional_member_count.total - 1,
                    },
                  }))
                }
              >
                -
              </Button>
              <InnerInput
                placeholder={`Jumlah ${selectedProtection === 'family' ? 'Keluarga' : 'Wisatawan'} (min ${selectedProtection === 'group' ? 2 : 0}, max ${selectedProtection === 'family' ? 4 : 9})`}
                onChange={(e) => setAdditionalCountInput(e.target.value)}
                onKeyPress={(e) => {
                  if (
                    !/[0-9]/.test(e.key) &&
                    e.key !== 'Backspace' &&
                    e.key !== 'Delete' &&
                    e.key !== 'Tab' &&
                    e.key !== 'Enter' &&
                    e.key !== 'ArrowLeft' &&
                    e.key !== 'ArrowRight'
                  ) {
                    e.preventDefault()
                  }
                }}
                onBlur={() => {
                  const value = parseInt(additionalCountInput) || 0
                  const minVal = selectedProtection === 'group' ? 2 : 0
                  const maxVal = selectedProtection === 'family' ? 4 : 99
                  const clampedValue = Math.min(Math.max(value, minVal), maxVal)
                  setFormValues((formValue) => ({
                    ...formValue,
                    additional_member_count: {
                      ...formValue.additional_member_count,
                      total: clampedValue,
                    },
                  }))
                  setAdditionalCountInput(clampedValue.toString())
                }}
                name="additional_count"
                value={additionalCountInput}
                className="select-buttons three-buttons input-travel-count"
                style={{ textAlign: 'center', height: 'auto' }}
                type="number"
              />
              <Button
                className={`select-buttons three-buttons ${formValues.additional_member_count.total >= 99 ? 'disabled-buttons' : selectedProtection === 'family' && formValues.additional_member_count.total >= 4 ? 'disabled-buttons' : ''}`}
                disabled={
                  (selectedProtection === 'family' &&
                    formValues.additional_member_count.total >= 4) ||
                  (selectedProtection === 'group' &&
                    formValues.additional_member_count.total >= 9)
                }
                onClick={() =>
                  setFormValues((formValue) => ({
                    ...formValue,
                    additional_member_count: {
                      ...formValue.additional_member_count,
                      total: formValue.additional_member_count.total + 1,
                    },
                  }))
                }
              >
                +
              </Button>
            </Row>
            <CustomText
              size="12px"
              color={AgentColorPallette.regular}
              style={{ textAlign: 'center', marginTop: '8px' }}
            >
              (Klik form untuk isi manual)
            </CustomText>
          </div>
        )
        break
      case 'dropdown':
        componentField = (
          <Select
            name={name}
            options={dropdownOptions}
            onChange={(e) =>
              setFormValues((formValue) => ({
                ...formValue,
                additional_member_count: {
                  ...formValue.additional_member_count,
                  kids: parseInt(e),
                },
              }))
            }
            value={defaultValues}
            displayKey="title"
            dataKey="value"
            hidePlaceholder
            className="mg-15"
          />
        )
        break
      default:
        componentField = (
          <InnerInput
            placeholder={placeholder}
            onChange={(e) => onChange(e.target.value)}
            name={name}
            className="mg-15"
            value={defaultValues}
          />
        )
    }

    return (
      <>
        <Row align="center" justify="space-between">
          <CustomText
            size="15px"
            color={AgentColorPallette.regular}
            weight={700}
          >
            {title}
          </CustomText>
        </Row>
        {componentField}
      </>
    )
  }

  return (
    <Container
      title={LANG_STRINGS.trip}
      showinnerHeader
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      displayBackButton
      hideBottomTabs
      onBackClick={handleBackButton}
    >
      <PolicyStepsHeader stepsData={TRAVEL_STEPS} activeCount={1} />
      <TravelDetailStyle>
        {Object.values(fieldData).map(
          (field) =>
            field.render &&
            renderFormField(
              field.label,
              field.type,
              field.name,
              field.dropdownOptions,
              field.placeholder,
              field.handleChange,
              field.defaultValues,
              field.defaultOrigin,
              field.defaultDestination
            )
        )}
        {selectedProtection === 'individual' && (
          <StatusInfoCard
            info={
              <span>
                <b>Individu</b>
                <br />
                <div className="info-text-group">
                  Pilih opsi ini jika hanya ingin mengasuransikan{' '}
                  <b>1 orang dewasa</b> umur <b>17 tahun keatas</b> untuk
                  perjalanan ini
                </div>
              </span>
            }
            noIcon
            bgColor="#DCF0FA"
            textWidth="100%"
          />
        )}
        {selectedProtection === 'family' && (
          <StatusInfoCard
            info={
              <div>
                <span>
                  <b>Keluarga</b>
                  <div className="info-text-group">
                    Pilih opsi ini jika bepergian bersama <b>keluarga inti</b>{' '}
                    dengan ketentuan:
                    <ul className="info-text-family">
                      <li>Suami dan Istri</li>
                      <li>
                        Ibu dan/atau Bapak bersama anak - anak berusia{' '}
                        <b>di bawah 17 tahun</b>.
                      </li>
                      <li>
                        Anak berusia <b>17 tahun ke atas tidak dapat</b>{' '}
                        dimasukkan ke dalam paket keluarga. Mereka harus membeli
                        plan <b>Individu</b> atau <b>Grup</b>.
                      </li>
                      <li>
                        Plan Keluarga hanya berlaku untuk keluarga inti (Bapak,
                        Ibu, Anak) dan <b>tidak dapat diwakilkan</b> oleh wali
                        atau anggota keluarga lainnya.
                      </li>
                      <li>
                        Anak <b>di bawah 17 tahun wajib didampingi orang tua</b>
                        , tidak dapat menggunakan pendamping anggota keluarga
                        lain.
                      </li>
                    </ul>
                  </div>
                </span>
                <span>
                  <b>Contoh:</b>
                  <ul className="info-text-family">
                    <li>
                      Bapak memiliki 2 anak, dan 1 anak sudah berusia
                      <b>di atas 17 tahun</b>. Maka Bapak dan 1 anak{' '}
                      <b>di bawah 17 tahun</b> membeli plan <b>Keluarga</b>, dan
                      anak yang berusia <b>di atas 17 tahun</b> membeli plan{' '}
                      <b>Individu</b>.
                    </li>
                    <li>
                      Bapak dan Ibu memiliki 4 anak, dan 2 anak sudah berusia{' '}
                      <b>di atas 17 tahun</b>. Maka Bapak, Ibu, dan 2 anak{' '}
                      <b>di bawah 17 tahun</b> membeli plan <b>Keluarga</b>,
                      sedangkan 2 anak <b>di atas 17 tahun</b> dapat membeli
                      polis plan <b>Grup</b>.
                    </li>
                  </ul>
                </span>
              </div>
            }
            noIcon
            bgColor="#DCF0FA"
            textWidth="100%"
          />
        )}
        {selectedProtection === 'group' && (
          <StatusInfoCard
            info={
              <span>
                <b>Group</b>
                <br />
                <div className="info-text-group">
                  <ul className="info-text-family">
                    <li>
                      Pilih opsi ini jika bepergian bersama kumpulan orang
                      dewasa, seluruhnya berusia <b>di atas 17 tahun</b>.
                    </li>
                    <li>
                      Berlaku untuk minimal <b>2 orang</b> dan maksimal hingga{' '}
                      <b>100 orang</b>.
                    </li>
                    <li>
                      Tidak boleh ada anak <b>di bawah 17 tahun</b> dalam paket
                      Grup.
                    </li>
                  </ul>
                </div>
              </span>
            }
            noIcon
            bgColor="#DCF0FA"
            textWidth="100%"
          />
        )}
      </TravelDetailStyle>
      <Footer>
        <Button
          className="submit-button"
          onClick={() => handleSubmit(formValues)}
        >
          LANJUT
        </Button>
      </Footer>
    </Container>
  )
}

export default TravelDetailContainer
